<div style="padding:18px 20px;border-radius:16px;background:linear-gradient(135deg,#0f2440 0%,#153a4d 100%);border:1px solid rgba(83,214,206,0.28);margin:18px 0;">
    <div style="font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:#9de7e0;margin-bottom:8px;">Ton accès FCC</div>
    <div style="color:#ffffff;line-height:1.75;">
        <strong>Application Forever Card principale :</strong> {{APP_LINK}} <br />
        <strong>Tableau de bord :</strong> {{DASHBOARD_LINK}}
    </div>
</div>

